import React, { useState } from 'react';
import { TabView } from 'primereact/tabview';

export default function Accessibility() {
    const [value, setValue] = useState('');
    
    return (
        <div>
            <label htmlFor="tabView-accessibility">Accessible TabView</label>
            <TabView 
                id="tabView-accessibility"
                value={value} 
                onChange={(e) => setValue(e.target.value)}
                aria-label="Accessible TabView input"
                placeholder="Enter tabView"
            />
        </div>
    );
}